#include <condition_variable>
#include <deque>
#include <mutex>
using namespace std;

class BoundedBlockingQueue {
    int cap;
    deque<int> q;
    mutex m;
    condition_variable notFull, notEmpty;
public:
    BoundedBlockingQueue(int capacity) : cap(capacity) {}

    void enqueue(int element) {
        unique_lock<mutex> lk(m);
        notFull.wait(lk, [&] { return (int)q.size() < cap; });
        q.push_back(element);
        notEmpty.notify_one();
    }

    int dequeue() {
        unique_lock<mutex> lk(m);
        notEmpty.wait(lk, [&] { return !q.empty(); });
        int val = q.front();
        q.pop_front();
        notFull.notify_one();
        return val;
    }

    int size() {
        lock_guard<mutex> lk(m);
        return q.size();
    }
};

