        this.cap = capacity;
        this.q = [];
        this.waiting = [];
    }

    _wait(pred) {
        return new Promise((resolve) => {
            const check = () => {
                if (pred()) resolve();
                else this.waiting.push(check);
            };
            check();
        });
    }

    async enqueue(element) {
        await this._wait(() => this.q.length < this.cap);
        this.q.push(element);
        this._wake();
    }

    async dequeue() {
        await this._wait(() => this.q.length > 0);
        const val = this.q.shift();
        this._wake();
        return val;
    }

    _wake() {
        if (this.waiting.length) {
            const fn = this.waiting.shift();
            setImmediate(fn);
        }
    }

    size() {
        return this.q.length;
    }
}

