class BoundedBlockingQueue {
    constructor(capacity) {
        this.q = [];
        this.slots = capacity;
        this.items = 0;
        this.mtx = null;
        this.slotWaiters = [];
        this.itemWaiters = [];
    }

    _acquire(getCount, dec, waiters) {
        return new Promise((resolve) => {
            const tryAcq = () => {
                if (getCount() > 0) { dec(); resolve(); }
                else waiters.push(tryAcq);
            };
            tryAcq();
        });
    }

    _release(waiters) {
        if (waiters.length) setImmediate(waiters.shift());
    }

    async enqueue(element) {
        await this._acquire(() => this.slots, () => this.slots--, this.slotWaiters);
        this.q.push(element);
        this.items++;
        this._release(this.itemWaiters);
    }

    async dequeue() {
        await this._acquire(() => this.items, () => this.items--, this.itemWaiters);
        const val = this.q.shift();
        this.slots++;
        this._release(this.slotWaiters);
        return val;
    }

    size() {
        return this.q.length;
    }
}
